```js
{
    cache: {
        enabled: true,
        diagnostics: {
            enabled: true,
            includeTenant: true
        },
        cacheability: {
            enabled: true,
            maxPayloadBytes: 262144,
            allowSensitiveFields: false,
            skipEmptyResults: false,
            skipBinaryPayloads: true,
            handlerFailureMode: 'failClosed',
            policyHandlers: []
        },
        invalidation: {
            crossNode: true,
            eventName: 'cacheInvalidation'
        },
        default: {
            channels: {
                router: {
                    enabled: true,
                    fallback: true,
                    engine: 'local'
                },
                schema: {
                    enabled: true,
                    fallback: true,
                    engine: 'local'
                }
            },
            engines: {
                local: {
                    enabled: true,
                    ttl: 100
                },
                redis: {
                    enabled: false,
                    ttl: 100
                }
            }
        }
    }
}
